// ===== v22ruin (package RU): ruined buildings, new building types, the rubble tile =====
// Save rule (v22core): a block changes only when World.legacy22(sb) is false, i.e. it has no delta from a pre-v22 save.
// Such a block is generated by this package the first time and gets its -22 record, so after a reload it is still
// "new" and its props keep their indexes. A legacy block is left exactly as the older generator made it.
//  - T.RUBBLE (id 28): a hole left by a broken wall or window. Walkable ground, texture tex22_rubble (dirt until it exists).
//  - Ruined buildings: b.dmg 0.2-0.9 on md 70% / sl 40% / tt 15% of the buildings (the start house never). Intact
//    buildings get b.dmg = 0. Walls (not corners) and windows may turn into holes, floors scorch, debris props are
//    appended at the end of the block. v22floors reads b.dmg for the roof.
//  - New types: a zone 1-2 block that v21 does not own (v21 owns its hospital/mall/restaurant hash range) becomes a
//    district of four lots. Each lot is one new building (b.type = its key, b.floors set) or an open parking lot.
//    Shares of all blocks in the zone: about 45% of zone 2 and 25% of zone 1. Furniture follows v21world's rule:
//    a solid piece is kept only if every walkable tile of the building stays reachable from its doors.
//  - Every prop is created whatever the art is (indexes stay). A prop with no image at all is culled (dead, as v21
//    does); a debris or vehicle prop falls back to a sprite that exists (realm prop or f21 furniture).
(function () {
  // ---------- tile ----------
  const freeId = n => { const used = new Set(Object.values(T)); while (used.has(n)) n++; return n; };
  T.RUBBLE = freeId(28);                                       // 28 is free (13-24 snow..leaves, 25 deep, 26-27 v21terrain)
  MINI_COL[T.RUBBLE] = [92, 84, 72];

  const isWaterT = t => t === T.WATER || t === T.DEEP || t === T.LAVA;
  const isFloorT = t => t === T.WOOD || t === T.TILEF;
  const near = (list, x, y, r) => list.some(([dx, dy]) => Math.max(Math.abs(dx - x), Math.abs(dy - y)) <= r);
  const fillTiles = (W, L, t) => { for (let y = L[1]; y <= L[3]; y++) for (let x = L[0]; x <= L[2]; x++) W.set(x, y, t); };
  const DIRS4 = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const TAU2 = Math.PI * 2;

  // ---------- rules ----------
  const RATE = { md: 0.70, sl: 0.40, tt: 0.15 };                        // share of buildings that are ruined
  // hash share among the blocks v21 leaves alone. The town/village generator runs only in about 84% of the zone 1-2
  // blocks (the rest are points of interest), so 0.71 and 0.38 give about 45% of zone 2 and 25% of zone 1 in all.
  const DIST = { 1: 0.38, 2: 0.71 };
  const FIELD_KINDS = ['farm'];
  const POOL = {
    mod: { 2: ['school', 'police', 'fire', 'gas', 'church', 'factory', 'warehouse', 'hotel', 'highrise', 'supermarket', 'pharmacy', 'bank', 'checkpoint', 'parking'],
           1: ['school', 'church', 'fire', 'gas', 'pharmacy', 'supermarket', 'farm', 'parking', 'checkpoint', 'police'] },
    tt: { 2: ['dojo', 'scripture', 'alchemy', 'escort', 'inn', 'yamen', 'temple', 'smithy', 'market', 'farm'],
          1: ['temple', 'smithy', 'market', 'farm', 'inn', 'dojo', 'scripture', 'escort', 'alchemy', 'yamen'] },
  };
  const ruGrp = () => (RL.id === 'tt' ? 'tt' : 'mod');
  // a building spec. inn/out: [src:key, count, container, solid]; src 'f22' = new sprite (fallback in FB), 'f21' = old furniture
  const B = (name, w, h, fl, roof, floor, doorW, rooms, boxes, loot, inn, out = []) => ({ name, w, h, fl, roof, floor, doorW, rooms, boxes, loot, in: inn, out });
  const TYPES = {
    mod: {
      school: B('Trường học', 11, 9, 1, 0, 'tile', 2, 2, 2, 'r22_school',
        [['f22:schooldesk', 6, null, 1], ['f22:blackboard', 1, null, 0], ['f21:bookshelf', 2, 'r22_school', 1], ['f21:desk', 1, null, 1]],
        [['f21:plantpot', 2, null, 0]]),
      police: B('Đồn cảnh sát', 11, 8, 2, 0, 'tile', 2, 3, 1, 'r22_police',
        [['f22:locker', 2, 'armor', 1], ['f22:cellbars', 2, null, 1], ['f21:cabinet', 2, 'r22_police', 1], ['f21:desk', 1, null, 1]],
        [['f22:policecar', 1, 'car', 1]]),
      fire: B('Trạm cứu hỏa', 10, 8, 2, 1, 'tile', 2, 2, 1, 'r22_fire',
        [['f22:locker', 2, 'armor', 1], ['f21:cabinet', 1, 'r22_fire', 1]],
        [['f22:firetruck', 1, 'car', 1]]),
      gas: B('Cây xăng', 5, 4, 1, 1, 'tile', 1, 1, 0, 'r22_gas',
        [['f21:checkout', 1, 'r22_gas', 1]],
        [['f22:gaspump', 3, 'gas', 1]]),
      church: B('Nhà thờ', 9, 11, 1, 0, 'wood', 2, 1, 1, 'r22_church',
        [['f22:pews', 6, null, 0], ['f22:altar', 1, null, 1], ['f21:plantpot', 2, null, 0], ['f21:cabinet', 1, 'r22_church', 1]]),
      factory: B('Nhà máy', 11, 9, 1, 1, 'tile', 2, 2, 2, 'r22_factory',
        [['f22:machine', 4, 'r22_factory', 1], ['f22:pallets', 3, 'crate', 1], ['f21:shelf', 1, 'r22_factory', 1]]),
      warehouse: B('Kho hàng', 11, 8, 1, 1, 'tile', 3, 1, 2, 'r22_warehouse',
        [['f22:pallets', 4, 'crate', 1], ['f22:forklift', 1, 'car', 1], ['f21:shelf', 2, 'crate', 1]]),
      hotel: B('Khách sạn', 9, 9, 3, 0, 'wood', 2, 3, 1, 'r22_hotel',
        [['f22:bunkbed', 4, 'house', 1], ['f21:table', 2, null, 1], ['f21:fridge', 1, 'fridge', 1], ['f21:shelf', 1, 'house', 1]]),
      highrise: B('Chung cư cao tầng', 8, 8, 5, 0, 'tile', 2, 3, 1, 'house',
        [['f21:bed', 2, null, 1], ['f21:sofa', 1, null, 1], ['f21:table', 1, null, 1], ['f21:wardrobe', 1, 'armor', 1], ['f21:stove', 1, 'kitchen', 1], ['f21:tv', 1, null, 1]]),
      supermarket: B('Siêu thị', 12, 9, 1, 1, 'tile', 3, 1, 2, 'r22_super',
        [['f21:shelf', 6, 'r22_super', 1], ['f21:checkout', 2, 'r22_super', 1], ['f21:vending', 1, 'r22_super', 1]]),
      pharmacy: B('Nhà thuốc', 7, 6, 1, 0, 'wood', 1, 1, 1, 'r22_pharm',
        [['f21:medcab', 2, 'r22_pharm', 1], ['f21:checkout', 1, 'r22_pharm', 1], ['f21:cabinet', 1, 'r22_pharm', 1]]),
      bank: B('Ngân hàng', 10, 7, 2, 0, 'tile', 2, 2, 0, 'r22_bank',
        [['f22:vault', 1, 'r22_bank', 1], ['f21:desk', 2, null, 1], ['f21:cabinet', 2, 'r22_bank', 1]]),
      checkpoint: B('Chốt quân sự', 8, 6, 1, 1, 'tile', 2, 1, 1, 'ammo',
        [['f21:rack', 1, 'armor', 1], ['f21:cabinet', 1, 'ammo', 1]],
        [['f22:sandbags', 6, null, 1]]),
      farm: B('Trang trại', 8, 6, 1, 1, 'wood', 2, 1, 1, 'r22_farm',
        [['f21:shelf', 1, 'crate', 1]],
        [['f22:silo', 1, 'r22_farm', 1], ['f22:tractor', 1, 'car', 1]]),
    },
    tt: {
      dojo: B('Võ đường', 11, 9, 1, 0, 'wood', 2, 1, 1, 'r22_dojo',
        [['f22:dummy', 3, null, 1], ['f22:weaponrack', 2, 'armor', 1], ['f21:rack', 1, 'armor', 1]]),
      scripture: B('Tàng kinh các', 9, 11, 2, 0, 'wood', 2, 2, 0, 'r22_scripture',
        [['f22:scrollrack', 4, 'r22_scripture', 1], ['f22:teatable', 1, null, 1], ['f21:bookshelf', 2, 'r22_scripture', 1], ['f21:table', 1, null, 1]]),
      alchemy: B('Luyện đan phòng', 8, 7, 1, 0, 'tile', 1, 2, 1, 'r22_alchemy',
        [['f21:cabinet', 2, 'r22_alchemy', 1], ['f22:herbbasket', 2, 'herb', 0], ['f21:stove', 1, 'r22_alchemy', 1], ['f21:table', 1, null, 1]]),
      escort: B('Tiêu cục', 10, 8, 1, 1, 'tile', 2, 2, 1, 'r22_escort',
        [['f22:weaponrack', 1, 'armor', 1], ['f21:table', 1, null, 1], ['f21:cabinet', 1, 'r22_escort', 1]],
        [['f22:cart', 2, 'crate', 1]]),
      inn: B('Khách điếm', 9, 9, 3, 1, 'wood', 2, 3, 1, 'r22_inn',
        [['f21:bed', 4, 'house', 1], ['f21:table', 3, null, 1], ['f21:shelf', 1, 'r22_inn', 1], ['f21:stove', 1, 'kitchen', 1]]),
      yamen: B('Nha môn', 10, 8, 2, 0, 'tile', 2, 2, 0, 'r22_yamen',
        [['f21:table', 2, null, 1], ['f21:cabinet', 2, 'r22_yamen', 1], ['f22:cellbars', 2, null, 1]],
        [['f22:drum', 1, null, 1]]),
      temple: B('Chùa', 9, 11, 1, 0, 'wood', 2, 1, 1, 'r22_temple',
        [['f22:buddha', 1, null, 1], ['f22:incense', 4, null, 0], ['f21:plantpot', 2, null, 0], ['f21:cabinet', 1, 'r22_temple', 1]]),
      smithy: B('Lò rèn', 8, 7, 1, 1, 'tile', 2, 1, 1, 'r22_smithy',
        [['f22:anvil', 1, null, 1], ['f21:stove', 1, 'r22_smithy', 1], ['f21:rack', 1, 'armor', 1], ['f21:shelf', 1, 'crate', 1]]),
      market: B('Chợ', 11, 8, 1, 1, 'tile', 2, 1, 1, 'market',
        [['f21:vending', 2, 'market', 1], ['f21:checkout', 1, 'market', 1]],
        [['f22:cart', 3, 'crate', 1]]),
      farm: B('Nông trại', 8, 6, 1, 1, 'wood', 2, 1, 1, 'r22_farm',
        [['f21:shelf', 1, 'crate', 1]],
        [['f22:herbbasket', 3, 'herb', 0]]),
    },
  };
  // fallback sprite for a f22 furniture key: an f21 key, or '~x' = RL.props.x (first entry), null = culled
  const FB = {
    box: '~crate', schooldesk: 'table', blackboard: 'tv', locker: 'wardrobe', cellbars: 'rack', gaspump: '~barrel', pews: '~bench', altar: 'table',
    machine: 'stove', pallets: '~crate', forklift: '~cars', vault: 'cabinet', bunkbed: 'bed', policecar: '~cars', firetruck: '~cars',
    tractor: '~cars', silo: '~barrel', sandbags: '~barrier', dummy: '~bench', weaponrack: 'rack', scrollrack: 'shelf', teatable: 'table',
    herbbasket: 'plantpot', drum: '~barrel', buddha: 'plantpot', incense: 'plantpot', cart: '~crate', anvil: '~rocks',
  };
  const VEH = ['policecar', 'firetruck', 'forklift', 'tractor'];
  // debris: image key (r22_<grp>_<k>) and fallback
  const DEBRIS = {
    mod: {
      in: [{ k: 'rubble1', fb: '~rocks' }, { k: 'rubble2', fb: '~rocks' }, { k: 'rubble3', fb: '~rocks' }],
      out: [{ k: 'rubble1', fb: '~rocks' }, { k: 'crater', fb: '~rocks' }, { k: 'trash', fb: '~trash', cont: 'trash' },
            { k: 'wallh', fb: '~fence', solid: 1, r: 10 }, { k: 'wallv', fb: '~fence', solid: 1, r: 10 }, { k: 'sofa', fb: 'sofa' }],
    },
    tt: {
      in: [{ k: 'rubble', fb: '~rocks' }],
      out: [{ k: 'rubble', fb: '~rocks' }, { k: 'pillar', fb: '~barrel', solid: 1, r: 10 }, { k: 'lantern', fb: '~lamp' },
            { k: 'stones', fb: '~rocks' }, { k: 'roofdebris', fb: '~rocks' }],
    },
  };
  // wrecks on road tiles of urban blocks: probability per road tile (md; sl half; tt its own list)
  const ROAD_WRECK = {
    mod: [{ k: 'carwreck1', fb: '~cars', p: 0.0015, solid: 1, r: 12, cont: 'car' }, { k: 'carwreck2', fb: '~cars', p: 0.0010, solid: 1, r: 12, cont: 'car' },
          { k: 'bus', fb: '~big', p: 0.0003, solid: 1, r: 18 }, { k: 'pole', fb: '~lamp', p: 0.0006 }, { k: 'crater', fb: '~rocks', p: 0.0008 }],
    tt: [{ k: 'cart', fb: '~crate', p: 0.0020, solid: 1, r: 12, cont: 'crate' }, { k: 'stones', fb: '~rocks', p: 0.0014 }, { k: 'lantern', fb: '~lamp', p: 0.0010 }],
  };
  // loot of the new containers (existing item ids only)
  Object.assign(LOOT, {
    r22_school: [['battery', 3, 1, 2], ['choco', 3, 1, 1], ['food', 2, 1, 1], ['water', 2, 1, 1], ['bandage', 1.5, 1, 1], ['flower', 1, 1, 1]],
    r22_police: [['ammo_pistol', 4, 6, 12], ['ammo_shell', 2, 3, 6], ['ammo_rifle', 2, 8, 16], ['bandage', 2, 1, 1], ['medkit', 1, 1, 1], ['grenade', 1, 1, 1]],
    r22_fire: [['medkit', 2, 1, 1], ['bandage', 3, 1, 2], ['water', 2, 1, 1], ['scrap', 2, 1, 2], ['gas', 1, 1, 1]],
    r22_gas: [['gas', 5, 1, 2], ['energy', 2, 1, 1], ['choco', 2, 1, 1], ['water', 2, 1, 1], ['battery', 1, 1, 1]],
    r22_church: [['food', 2, 1, 1], ['water', 2, 1, 1], ['pills', 2, 1, 1], ['flower', 2, 1, 2], ['bandage', 2, 1, 1], ['energy', 1, 1, 1]],
    r22_factory: [['scrap', 6, 2, 3], ['planks', 3, 1, 2], ['battery', 2, 1, 1], ['gas', 1, 1, 1], ['key', 0.5, 1, 1]],
    r22_warehouse: [['planks', 4, 1, 2], ['scrap', 3, 1, 2], ['food', 2, 1, 1], ['water', 2, 1, 1], ['ammo_pistol', 1, 4, 8]],
    r22_hotel: [['food', 3, 1, 2], ['water', 3, 1, 2], ['bandage', 2, 1, 1], ['choco', 2, 1, 1], ['key', 0.5, 1, 1], ['pills', 1, 1, 1]],
    r22_super: [['water', 5, 1, 2], ['food', 5, 1, 2], ['choco', 3, 1, 2], ['energy', 3, 1, 2], ['flower', 1, 1, 1]],
    r22_pharm: [['bandage', 4, 1, 2], ['pills', 4, 1, 2], ['medkit', 1.5, 1, 1], ['water', 1, 1, 1]],
    r22_bank: [['gold', 4, 20, 50], ['battery', 1, 1, 1], ['key', 0.5, 1, 1]],
    r22_farm: [['food', 5, 1, 2], ['water', 3, 1, 1], ['energy', 1, 1, 1], ['planks', 2, 1, 2], ['gas', 1, 1, 1]],
    r22_dojo: [['bandage', 3, 1, 2], ['pills', 2, 1, 2], ['food', 2, 1, 1], ['medkit', 1, 1, 1], ['molotov', 1, 1, 1]],
    r22_scripture: [['pills', 3, 1, 2], ['energy', 2, 1, 1], ['battery', 2, 1, 1], ['food', 1, 1, 1], ['flower', 1, 1, 1]],
    r22_alchemy: [['pills', 4, 1, 2], ['medkit', 1, 1, 1], ['gas', 2, 1, 2], ['battery', 2, 1, 1], ['energy', 1, 1, 1]],
    r22_escort: [['gold', 3, 10, 25], ['ammo_pistol', 2, 4, 8], ['ammo_rifle', 1, 6, 12], ['food', 2, 1, 1], ['water', 2, 1, 1]],
    r22_inn: [['food', 4, 1, 2], ['water', 4, 1, 2], ['choco', 2, 1, 1], ['energy', 2, 1, 1], ['gold', 1, 5, 15]],
    r22_yamen: [['gold', 4, 8, 20], ['key', 0.5, 1, 1], ['pills', 2, 1, 1], ['food', 1, 1, 1]],
    r22_temple: [['pills', 3, 1, 2], ['flower', 3, 1, 2], ['food', 2, 1, 1], ['water', 2, 1, 1], ['energy', 1, 1, 1]],
    r22_smithy: [['scrap', 5, 1, 3], ['planks', 2, 1, 2], ['gas', 2, 1, 1], ['battery', 1, 1, 1]],
  });

  // ---------- sprites: own art, else a fallback, else null (the prop is then culled) ----------
  const ruFb = fb => {
    if (!fb) return null;
    if (fb[0] === '~') { const v = RL.props[fb.slice(1)]; const n = Array.isArray(v) ? v[0] : v; return n || null; }
    return 'f21_' + ruGrp() + '_' + fb;
  };
  const ruImg = (name, fb) => {
    if (IMG[name]) return name;
    const f = ruFb(fb); return f && IMG[f] ? f : null;
  };
  // every prop is created (the index stays the same); a prop with no image at all is culled, like v21
  const ruAdd = (W, name, fb, x, y, o) => {
    const img = ruImg(name, fb), p = W.addProp(img || name, x, y, Object.assign({ kind: name }, o));
    if (!img) p.cull = true;
    return p;
  };

  // ---------- which blocks become districts ----------
  const v21Owns = sb => !(sb.sx === 0 && sb.sy === 0) && (sb.zone === 2 ? h3(sb.sx, sb.sy, 2101) < 0.24 : sb.zone === 1 ? h3(sb.sx, sb.sy, 2101) < 0.10 : false);
  const wants = (sx, sy, zone) => (zone === 1 || zone === 2) && h3(sx, sy, 2202) < DIST[zone];
  const isDistrict = sb => !!sb._ru && !v21Owns(sb) && wants(sb.sx, sb.sy, sb.zone);

  // ---------- furniture helpers (same method as v21world: keep the doors reachable) ----------
  const expand = list => {
    const out = [];
    for (const [src, n, cont, solid] of list || []) { const [s, key] = src.split(':'); for (let k = 0; k < n; k++) out.push({ s, key, cont, solid: !!solid }); }
    return out;
  };
  const shuffle = (arr, salt) => arr.map((e, k) => [h3(k, salt, 2311), e]).sort((p, q) => p[0] - q[0]).map(p => p[1]);
  const bldGrid = (W, sb, b) => {
    const Wd = b.x1 - b.x0 + 1, Hd = b.y1 - b.y0 + 1, blk = new Uint8Array(Wd * Hd);
    for (let y = b.y0; y <= b.y1; y++) for (let x = b.x0; x <= b.x1; x++) if (W.isSolidT(W.get(x, y))) blk[(y - b.y0) * Wd + (x - b.x0)] = 1;
    for (const p of sb.props) {
      if (!p.solid || !p.circles) continue;
      for (const c of p.circles) {
        if (c.r < 9) continue;
        const tx = Math.floor(c.x / TILE), ty = Math.floor(c.y / TILE);
        if (tx >= b.x0 && tx <= b.x1 && ty >= b.y0 && ty <= b.y1) blk[(ty - b.y0) * Wd + (tx - b.x0)] = 1;
      }
    }
    return { W: Wd, blk };
  };
  // interior walkable tiles the doors cannot reach
  const unreached = (b, g) => {
    const Wd = g.W, blk = g.blk, Hd = blk.length / Wd, seen = new Uint8Array(blk.length), q = [];
    for (const [dx, dy] of b.doors) { const i = (dy - b.y0) * Wd + (dx - b.x0); if (!blk[i] && !seen[i]) { seen[i] = 1; q.push(i); } }
    for (let h = 0; h < q.length; h++) {
      const i = q[h], x = i % Wd, y = (i - x) / Wd;
      for (const [ax, ay] of DIRS4) {
        const nx = x + ax, ny = y + ay; if (nx < 0 || ny < 0 || nx >= Wd || ny >= Hd) continue;
        const j = ny * Wd + nx; if (blk[j] || seen[j]) continue;
        seen[j] = 1; q.push(j);
      }
    }
    let bad = 0;
    for (let y = 1; y < Hd - 1; y++) for (let x = 1; x < Wd - 1; x++) { const i = y * Wd + x; if (!blk[i] && !seen[i]) bad++; }
    return bad;
  };
  const place = (W, sb, g, it, x, y, inside) => {
    const fb = it.s === 'f22' ? (FB[it.key] || null) : null;
    const name = (it.s === 'f22' ? 'f22_' : 'f21_') + g + '_' + it.key;
    const veh = VEH.includes(it.key);
    const p = ruAdd(W, name, fb, x * TILE + 16, y * TILE + 16, {
      solid: it.solid, r: it.solid ? (veh ? 16 : 12) : 0, container: it.cont || null, kind: 'furn22', fuel: veh ? 20 : 0,
    });
    if (inside && it.solid) for (const [dx, dy] of DIRS4) W.setOcc(x + dx, y + dy);   // keep the aisles open
    return p;
  };

  // ---------- districts ----------
  // one building in a lot: centred with a random offset, one tile of yard on each side, a door facing the block edge
  function lotBuilding(W, sb, L, i, kind, t) {
    const g = ruGrp(), LW = L[2] - L[0] + 1, LH = L[3] - L[1] + 1;
    const w = Math.min(t.w, LW - 2), h = Math.min(t.h, LH - 2);
    const x0 = L[0] + 1 + Math.floor(h3(sb.sx, sb.sy, 2270 + i) * (LW - 1 - w));
    const y0 = L[1] + 1 + Math.floor(h3(sb.sx, sb.sy, 2280 + i) * (LH - 1 - h));
    const x1 = x0 + w - 1, y1 = y0 + h - 1;
    const side = [i & 1 ? 'e' : 'w', i >> 1 ? 's' : 'n'][Math.floor(h3(sb.sx, sb.sy, 2290 + i) * 2)];
    const b = W.makeBuilding(x0, y0, x1, y1, {
      type: kind, name: t.name, floor: t.floor === 'wood' ? T.WOOD : T.TILEF, roof: RL.roofs[t.roof] || RL.roofs[0],
      doors: [side], doorW: t.doorW, rooms: t.rooms, containers: 0,   // boxes come from the furniture list (reachability checked)
    });
    b.floors = t.fl; b.dmg = 0;
    // roof texture 1..10 (tex22_roof_N): by building type, plus a hash step. Only when no earlier wrapper set one.
    if (b.roofStyle === undefined) b.roofStyle = 1 + (Object.keys(TYPES[g]).indexOf(kind) * 3 + Math.floor(h3(x0, y0, 2400) * 4)) % 10;
    const bi = sb.buildings.indexOf(b);
    const inList = t.boxes ? t.in.concat([['f22:box', t.boxes, t.loot, 1]]) : t.in;
    // inside: floor tiles of this building in hash order; a solid piece is kept only if no walkable tile gets cut off
    const cand = [];
    for (let y = b.y0 + 1; y < b.y1; y++) for (let x = b.x0 + 1; x < b.x1; x++) {
      const k = (y - sb.ty0) * SB + (x - sb.tx0);
      if (sb.bld[k] !== bi || sb.occ[k] || W.isSolidT(sb.tiles[k]) || near(b.doors, x, y, 1)) continue;
      cand.push([h3(x, y, 2300 + bi), x, y]);
    }
    cand.sort((p, q) => p[0] - q[0]);
    const grid = bldGrid(W, sb, b), Wd = grid.W;
    let bad = unreached(b, grid);
    const limit = Math.max(2, Math.floor((b.x1 - b.x0 - 1) * (b.y1 - b.y0 - 1) / 6));
    let placed = 0;
    for (const it of shuffle(expand(inList), 2310 + bi)) {
      if (placed >= limit) break;
      for (const [, x, y] of cand) {
        const k = (y - sb.ty0) * SB + (x - sb.tx0), j = (y - b.y0) * Wd + (x - b.x0);
        if (sb.occ[k] || grid.blk[j]) continue;
        if (it.solid) {
          grid.blk[j] = 1;
          const bad2 = unreached(b, grid);
          if (bad2 > bad) { grid.blk[j] = 0; continue; }
          bad = bad2;
        }
        place(W, sb, g, it, x, y, true); placed++;
        break;
      }
    }
    // yard: the lot tiles outside the building and its one-tile front; solid pieces keep 2 tiles from every door
    const yard = [];
    for (let y = L[1]; y <= L[3]; y++) for (let x = L[0]; x <= L[2]; x++) {
      if (x >= b.x0 - 1 && x <= b.x1 + 1 && y >= b.y0 - 1 && y <= b.y1 + 1) continue;
      const k = (y - sb.ty0) * SB + (x - sb.tx0);
      if (sb.occ[k] || sb.bld[k] >= 0 || !W.isGround(sb.tiles[k])) continue;
      yard.push([h3(x, y, 2320), x, y]);
    }
    yard.sort((p, q) => p[0] - q[0]);
    for (const it of shuffle(expand(t.out), 2330 + bi)) {
      for (const [, x, y] of yard) {
        const k = (y - sb.ty0) * SB + (x - sb.tx0);
        if (sb.occ[k] || (it.solid && near(b.doors, x, y, 2))) continue;
        place(W, sb, g, it, x, y, false);
        break;
      }
    }
    // a lamp, a tree or a bin now and then, as in the town streets
    const [x0l, y0l, x1l, y1l] = L;
    if (h3(x0l, y0l, 2381) < 0.5 && RL.props.lamp && W.free(x0l, y0l)) W.addProp(RL.props.lamp, x0l * TILE + 16, y0l * TILE + 16, { solid: false, light: 110 });
    if (h3(x0l, y0l, 2382) < 0.35) for (let k = 0; k < 2; k++) {
      W.tryTree(x0l + 1 + Math.floor(h3(x0l, y0l, 2383 + k) * (x1l - x0l - 1)), y0l + 1 + Math.floor(h3(y0l, x0l, 2385 + k) * (y1l - y0l - 1)), false);
    }
    if (h3(x1l, y1l, 2387) < 0.4 && RL.props.trash && W.free(x1l, y1l)) W.container(RL.props.trash[0], x1l, y1l, 'trash');
    return b;
  }
  function parkingLot(W, L) {
    for (let y = L[1] + 2; y <= L[3] - 2; y += 4) for (let x = L[0] + 1; x <= L[2] - 1; x += 3) {
      const h = h3(x, y, 2330);
      if (h < 0.45 || !W.free(x, y)) continue;
      ruAdd(W, 'r22_mod_carwreck' + (h < 0.725 ? 1 : 2), '~cars', x * TILE + 16, y * TILE + 16,
        { solid: true, r: 14, rot: Math.PI / 2 + (h3(x, y, 2331) - 0.5) * 0.2, container: 'car', fuel: 0 });
    }
  }
  // four lots (2x2) cover the whole interior of the block; a block with water in it keeps the old generator
  function buildDistrict(W, bk, sb) {
    for (let y = bk.y0; y <= bk.y1; y++) for (let x = bk.x0; x <= bk.x1; x++) if (isWaterT(W.get(x, y))) return false;
    const g = ruGrp(), pool = POOL[g][sb.zone], TY = TYPES[g];
    const mx = bk.x0 + ((bk.x1 - bk.x0 + 1) >> 1), my = bk.y0 + ((bk.y1 - bk.y0 + 1) >> 1);
    const lots = [[bk.x0, bk.y0, mx - 1, my - 1], [mx, bk.y0, bk.x1, my - 1], [bk.x0, my, mx - 1, bk.y1], [mx, my, bk.x1, bk.y1]];
    lots.forEach((L, i) => {
      const kind = pool[Math.floor(h3(sb.sx, sb.sy, 2250 + i) * pool.length)];
      fillTiles(W, L, FIELD_KINDS.includes(kind) ? T.FIELD : T.CONC);
      if (kind === 'parking') return parkingLot(W, L);
      lotBuilding(W, sb, L, i, kind, TY[kind]);
    });
    return true;
  }

  // ---------- ruin: holes, scorch, debris, trees, road wrecks (after the whole block is generated) ----------
  function ruin(W, sb) {
    const g = ruGrp(), start = sb.sx === 0 && sb.sy === 0, rate = RATE[RL.id] ?? RATE.sl, DB = DEBRIS[g];
    sb.buildings.forEach((b, bi) => {
      b.dmg = !start && h3(b.x0, b.y0, 2203) < rate ? +(0.2 + 0.7 * h3(b.x0, b.y0, 2204)).toFixed(2) : 0;
      if (!(b.dmg > 0)) return;
      const d = b.dmg, holes = [];
      for (let y = b.y0; y <= b.y1; y++) for (let x = b.x0; x <= b.x1; x++) {
        const k = (y - sb.ty0) * SB + (x - sb.tx0);
        if (sb.bld[k] !== bi) continue;
        const ex = x === b.x0 || x === b.x1, ey = y === b.y0 || y === b.y1, t = sb.tiles[k], r = h3(x, y, 2205);
        if (ex && ey) continue;                                                     // corners stay
        if (t === T.WALL) { if ((ex || ey) && r < d * 0.34) { sb.tiles[k] = T.RUBBLE; holes.push(k); } }   // outer walls only: no dead pockets
        else if (t === T.WINDOW) { if (r < d * 0.6) { sb.tiles[k] = T.RUBBLE; holes.push(k); } }
        else if (isFloorT(t) && r < d * 0.1) W.addDecal('scorch', x * TILE + 16, y * TILE + 16, h3(x, y, 2206) * TAU2, 0.9, 0.7);
      }
      // debris inside (floor tiles, hash order)
      const inside = [];
      for (let y = b.y0 + 1; y < b.y1; y++) for (let x = b.x0 + 1; x < b.x1; x++) {
        const k = (y - sb.ty0) * SB + (x - sb.tx0);
        if (sb.bld[k] === bi && !sb.occ[k] && isFloorT(sb.tiles[k])) inside.push([h3(x, y, 2340), x, y]);
      }
      inside.sort((p, q) => p[0] - q[0]);
      for (let k = 0; k < Math.min(1 + Math.floor(d * 3), inside.length); k++) {
        const [, x, y] = inside[k], e = DB.in[Math.floor(h3(x, y, 2341) * DB.in.length)];
        ruAdd(W, 'r22_' + g + '_' + e.k, e.fb, x * TILE + 16, y * TILE + 16, { solid: false, rot: h3(x, y, 2342) * TAU2 });
      }
      // debris outside: 2-3 tiles from the walls, never next to a door
      const ring = [];
      for (let y = b.y0 - 3; y <= b.y1 + 3; y++) for (let x = b.x0 - 3; x <= b.x1 + 3; x++) {
        const dd = Math.max(b.x0 - x, x - b.x1, b.y0 - y, y - b.y1);
        if (dd < 2 || dd > 3 || !W.free(x, y) || !W.isGround(W.get(x, y)) || near(b.doors, x, y, 2)) continue;
        ring.push([h3(x, y, 2350), x, y]);
      }
      ring.sort((p, q) => p[0] - q[0]);
      let outN = 0;
      for (const [, x, y] of ring) {
        if (outN >= 1 + Math.floor(d * 2)) break;
        if (!W.free(x, y)) continue;
        const e = DB.out[Math.floor(h3(x, y, 2351) * DB.out.length)];
        ruAdd(W, 'r22_' + g + '_' + e.k, e.fb, x * TILE + 16, y * TILE + 16, { solid: !!e.solid, r: e.r || 0, rot: h3(x, y, 2352) * TAU2, container: e.cont || null });
        outN++;
      }
      // a tree grows through a hole in a modern ruin
      if (g === 'mod' && d > 0.5 && holes.length && h3(b.x0, b.y0, 2360) < 0.5) {
        const k = holes.find(j => !sb.occ[j]);
        if (k !== undefined) {
          const x = sb.tx0 + (k % SB), y = sb.ty0 + Math.floor(k / SB);
          W.addProp(RL.props.trees[Math.floor(h3(x, y, 2361) * RL.props.trees.length)], x * TILE + 16, y * TILE + 16, { canopy: true, r: 9, layer: 3, rot: h3(x, y, 2362) * TAU2 });
        }
      }
    });
    // wrecks and fallen things on the road tiles of urban blocks
    if (sb.zone >= 1 && !start) {
      const table = g === 'tt' ? ROAD_WRECK.tt : ROAD_WRECK.mod, mult = RL.id === 'sl' ? 0.5 : 1;
      for (let y = 0; y < SB; y++) for (let x = 0; x < SB; x++) {
        const k = y * SB + x;
        if (sb.tiles[k] !== T.ROAD || sb.occ[k]) continue;
        const gx = sb.tx0 + x, gy = sb.ty0 + y, r = h3(gx, gy, 2370);
        let acc = 0;
        for (const e of table) {
          acc += e.p * mult;
          if (r >= acc) continue;
          if (W.free(gx, gy, 1)) ruAdd(W, 'r22_' + g + '_' + e.k, e.fb, gx * TILE + 16, gy * TILE + 16, { solid: !!e.solid, r: e.r || 0, rot: h3(gx, gy, 2371) * TAU2, container: e.cont || null });
          break;
        }
      }
    }
  }

  // ---------- generation wrappers ----------
  const go = World.genOver;
  World.genOver = function (sb) {
    sb._ru = this.mode === 'over' && !this.legacy22(sb);     // legacy block: nothing below runs
    const prev = this._gen; this._gen = sb;
    try {
      go.call(this, sb);
      if (sb._ru) ruin(this, sb);
    } finally { this._gen = prev; }
  };
  // the town / village / palace generator of a district block is replaced (v21 never owns these blocks)
  for (const name of ['genTown', 'genVillage', 'genPalace']) {
    const g = World[name];
    World[name] = function (bk) {
      const sb = this._gen;
      if (sb && isDistrict(sb) && buildDistrict(this, bk, sb)) return;
      return g.call(this, bk);
    };
  }

  // ---------- look: the rubble texture and a few bits on each rubble tile ----------
  const texOf0 = World.texOf;
  World.texOf = function (t) { return t === T.RUBBLE ? spr22('tex22_rubble', 'tex_dirt') : texOf0.call(this, t); };
  const rc0 = World.renderChunk;
  World.renderChunk = function (ctx, cx, cy) {
    rc0.call(this, ctx, cx, cy);
    for (let ty = cy * CH; ty < cy * CH + CH; ty++) for (let tx = cx * CH; tx < cx * CH + CH; tx++) {
      if (this.get(tx, ty) !== T.RUBBLE) continue;
      const X = tx * TILE, Y = ty * TILE, h = hash2(tx, ty);
      ctx.fillStyle = 'rgba(30,26,22,0.45)';
      ctx.fillRect(X + 2 + Math.floor(h * 16), Y + 3 + Math.floor(h * 13), 5 + Math.floor(h * 4), 3);
      ctx.fillRect(X + 6 + Math.floor((1 - h) * 14), Y + 19 - Math.floor(h * 7), 4, 3);
      ctx.fillStyle = 'rgba(210,200,180,0.22)';
      ctx.fillRect(X + 10, Y + 10, 3, 2);
    }
  };

  // for the smoke tests and for later packages
  World.ru22 = { wants, v21Owns, isDistrict, types: TYPES, rate: RATE };
})();
